/* Include the exact production comp_v11_ble_bulk_profile body generated by
 * the runner. Only clock, connection event state and official ACI boundaries
 * are simulated; OTA power/signature acceptance is not simulated here. */
#include <assert.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "../ble_directional_budget_recovery.h"
typedef uint8_t tBleStatus;
typedef enum {COMP_V11_BLE_BULK_NONE,COMP_V11_BLE_BULK_DEVICE_TO_HOST,
    COMP_V11_BLE_BULK_HOST_TO_DEVICE} comp_v11_ble_bulk_direction_t;
#define BLE_STATUS_SUCCESS 0u
#define CONFIG_DATA_LL_RX_ACL_CTRL_OFFSET 0xC4u
static bool ready,connection_secured,bulk_profile;
static uint8_t directional_budget_recovery;
static uint8_t bulk_rx_profile;
static const bool bulk_empty_rx_slots=true,bulk_renegotiate_dle=false;
static bool bulk_ci_requested,bulk_dle_issued,bulk_dle_waiting;
static bool dle_restore_attempted,dle_alignment_attempted;
static uint16_t connection,bulk_ci_previous_interval,dle_aligned_octets;
static uint8_t bulk_ci_attempts,bulk_ci_status,dle_attempts,dle_status;
static uint8_t dle_restore_status,dle_alignment_status,profile_status;
static uint32_t profile_retry,bulk_ci_ready_after,bulk_dle_ready_after,dle_ready_after;
static struct {uint16_t interval,tx_octets,tx_time,rx_time;uint8_t tx_phy,rx_phy;} transport;
static uint32_t now,config_calls,ci_calls,dle_calls;
static uint8_t applied[2],next_config_status;
static uint16_t last_ci;
static uint32_t HAL_GetTick(void) {return now;}
static void transport_trace(uint8_t reason,uint16_t value) {(void)reason;(void)value;}
static tBleStatus aci_hal_write_config_data(uint8_t offset,uint8_t length,const uint8_t *value)
{
    assert(offset==CONFIG_DATA_LL_RX_ACL_CTRL_OFFSET && length==2u);++config_calls;
    if(!next_config_status)memcpy(applied,value,2u);
    return next_config_status;
}
static tBleStatus aci_l2cap_connection_parameter_update_req(
    uint16_t handle,uint16_t min,uint16_t max,uint16_t latency,uint16_t timeout)
{
    assert(handle==connection && min==max && latency==0u && timeout==400u);
    ++ci_calls;last_ci=min;return BLE_STATUS_SUCCESS;
}
static tBleStatus hci_le_set_data_length(uint16_t handle,uint16_t octets,uint16_t duration)
{
    assert(handle==connection && octets==251u && duration==2120u);
    ++dle_calls;return BLE_STATUS_SUCCESS;
}
static uint16_t comp_v11_ble_bulk_aligned_octets(uint16_t octets,uint16_t duration,uint8_t phy,uint16_t interval)
{(void)octets;(void)duration;(void)phy;(void)interval;assert(false);return 0u;}
#include "production_bulk_profile.inc"
static void setup(void)
{
    ready=connection_secured=true;connection=1u;bulk_profile=bulk_rx_profile=false;
    directional_budget_recovery=0u;
    bulk_ci_requested=bulk_dle_issued=bulk_dle_waiting=false;
    dle_restore_attempted=dle_alignment_attempted=false;
    bulk_ci_attempts=0u;bulk_ci_previous_interval=0u;dle_attempts=0x81u;
    profile_retry=bulk_ci_ready_after=bulk_dle_ready_after=dle_ready_after=0u;
    now=1u;config_calls=ci_calls=dle_calls=0u;next_config_status=0u;
    transport.interval=48u;transport.tx_phy=transport.rx_phy=2u;transport.tx_octets=251u;transport.tx_time=965u;
    applied[0]=0u;applied[1]=32u;
}
static void profile(comp_v11_ble_bulk_direction_t direction)
{comp_v11_ble_bulk_profile(direction,direction!=COMP_V11_BLE_BULK_NONE,true,true);}
int main(void)
{
    setup();profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);
    assert(bulk_profile && bulk_rx_profile && applied[0]==7u && applied[1]==0u);
    profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);assert(ci_calls==1u && last_ci==6u);
    transport.interval=6u;
    profile(COMP_V11_BLE_BULK_HOST_TO_DEVICE);
    assert(bulk_profile && bulk_rx_profile==2u && applied[0]==7u && applied[1]==251u);
    assert(bulk_ci_requested && bulk_ci_attempts==1u && ci_calls==1u && dle_calls==0u && dle_attempts==0x81u);
    profile(COMP_V11_BLE_BULK_HOST_TO_DEVICE);assert(config_calls==2u && ci_calls==1u);
    puts("PASS active recording TX -> OTA RX changes RX budget without new CI/DLE ownership");

    next_config_status=0x64u;profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);
    assert(bulk_rx_profile==2u && applied[0]==7u && applied[1]==251u && config_calls==3u);
    ++now;profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);assert(config_calls==3u);
    now=1001u;next_config_status=0u;profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);
    assert(bulk_rx_profile && applied[0]==7u && config_calls==4u && ci_calls==1u);
    profile(COMP_V11_BLE_BULK_NONE);assert(!bulk_profile && bulk_rx_profile==0u && applied[0]==0u && applied[1]==32u);
    profile(COMP_V11_BLE_BULK_NONE);assert(last_ci==48u && ci_calls==2u && !bulk_ci_requested);
    puts("PASS failed direction change keeps actual RX state, bounded retry, normal release restores RX/CI");

    setup();profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);
    connection=0xffffu;connection_secured=false;
    comp_v11_ble_bulk_profile(COMP_V11_BLE_BULK_NONE,false,false,true);
    assert(!bulk_profile && bulk_rx_profile==0u && applied[0]==0u && applied[1]==32u);
    setup();next_config_status=0x64u;profile(COMP_V11_BLE_BULK_DEVICE_TO_HOST);
    assert(!bulk_profile && bulk_rx_profile==0u && applied[0]==0u && applied[1]==32u);
    puts("PASS disconnect release and failed activation never claim unapplied one-way configuration");
    setup();
    comp_v11_ble_bulk_profile(COMP_V11_BLE_BULK_NONE,true,true,true);
    assert(bulk_profile && bulk_rx_profile==0u && applied[0]==0u && applied[1]==32u);
    profile(COMP_V11_BLE_BULK_HOST_TO_DEVICE);
    assert(bulk_profile && bulk_rx_profile==2u && applied[0]==7u && applied[1]==251u);
    unsigned configured=config_calls;
    for(unsigned i=0;i<1000u;++i)profile(COMP_V11_BLE_BULK_HOST_TO_DEVICE);
    assert(config_calls==configured);
    comp_v11_ble_bulk_profile(COMP_V11_BLE_BULK_NONE,true,true,true);
    assert(bulk_profile && bulk_rx_profile==0u && applied[0]==0u && applied[1]==32u);
    puts("PASS idle bulk hint -> explicit OTA RX -> idle hint changes actual profile once; no repeated ACI");
    return 0;
}
